{
  "work_definition_version": 0,
  "task_family": "reconciliation",
  "model_id": "w1-k-b3-acme-beta-gamma-reconciliation",
  "provenance": {
    "producer": "goose-B3",
    "skill": "define-lab-process",
    "produced_at": "2026-08-21T15:48:00+03:00"
  },
  "purpose": "Reconcile supplier statement records with internal ledger book to identify and classify paid, pending, and unmatched transactions.",
  "sources": {
    "supplier": {
      "role_label": "Supplier Statement",
      "fixture": "supplier-statement.txt",
      "observed_fields": ["Date, Supplier Name, InvoiceNumber, Amount, Currency, Status"],
      "basis": "observed"
    },
    "ledger": {
      "role_label": "Internal Ledger Book",
      "fixture": "ledger-book.txt",
      "observed_fields": ["Date, ReferenceNumber, SupplierName, InvoiceNumber, Amount, Status, Notes"],
      "basis": "observed"
    }
  },
  "body": {
    "left": "supplier",
    "right": "ledger",
    "match_on": {
      "left_field": "InvoiceNumber",
      "right_field": "InvoiceNumber",
      "basis": "human_confirmed",
      "confirmation": "Q_reconciliation_rules"
    },
    "compare": [
      {
        "field": "Amount",
        "comparison": "within",
        "tolerance": "0.01",
        "basis": "human_confirmed",
        "confirmation": "Q_reconciliation_rules"
      }
    ],
    "classify": {
      "both_same": "matched_paid",
      "both_different": "amount_discrepancy",
      "only_left": "supplier_only_unrecorded",
      "only_right": "ledger_only_not_on_statement"
    },
    "output_order": "left_then_right",
    "on_duplicate_key": "refuse_run",
    "on_non_numeric": "refuse_run"
  },
  "output": {
    "reports_fields": [
      "InvoiceNumber",
      "Amount"
    ],
    "context_fields": [
      "Date",
      "Supplier Name",
      "Status"
    ],
    "provenance": {
      "reports_fields": {
        "basis": "human_confirmed",
        "confirmation": "Q_reconciliation_rules"
      },
      "context_fields": {
        "basis": "human_confirmed",
        "confirmation": "Q_reconciliation_rules"
      }
    }
  },
  "human_confirmations": [
    {
      "id": "Q_reconciliation_rules",
      "question": "Which field identifies the same record / invoice in both files? Should Amount be compared, and if so, how and with what tolerance? Is Currency part of the reconciliation rule? Which file is the source of truth for matching? Which fields should appear in the report row? Which fields are context for the report?",
      "answer": "InvoiceNumber. Yes, compare Amount numerically, within 0.01. No, Currency is not compared and is not part of the rule. Neither neither, both peers. The match key (InvoiceNumber) and the compared field (Amount). Date, Supplier Name, and Status.",
      "basis": "human_confirmed"
    }
  ],
  "open_questions": [],
  "requested_destination": "review_only",
  "requested_delivery": {
    "format": "json_discrepancy_report"
  },
  "requested_authority": null
}

